"""ORD_LINE renumbering migration for Meridian CRM 4.2."""

from collections import defaultdict
from typing import Any


def _numeric_line_number(value: Any) -> float:
    """Return a numeric sort key, preserving legacy empty-string-as-zero coercion."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted order lines and assign contiguous line numbers per order.

    Surviving lines are ordered within each order by their original LINE_NO using
    numeric comparison. The input list and its row dictionaries are not mutated.
    """
    grouped: dict[str, list[tuple[float, int, dict]]] = defaultdict(list)

    for input_index, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue

        order_id = str(row.get("ORD_ID", ""))
        grouped[order_id].append(
            (_numeric_line_number(row.get("LINE_NO", "")), input_index, row)
        )

    result: list[dict] = []
    for order_id in sorted(grouped):
        ordered_lines = sorted(grouped[order_id], key=lambda item: (item[0], item[1]))
        for new_line_number, (_, _, original_row) in enumerate(ordered_lines, start=1):
            renumbered_row = dict(original_row)
            renumbered_row["LINE_NO"] = new_line_number
            result.append(renumbered_row)

    return result
